class Solution:
    def minFallingPathSum(self, matrix: list[list[int]]) -> int:
        n = len(matrix)
        dp = [[0] * n for _ in range(n)]
        dp[0] = matrix[0][:]
        for r in range(1, n):
            for c in range(n):
                best = dp[r - 1][c]
                if c > 0:
                    best = min(best, dp[r - 1][c - 1])
                if c + 1 < n:
                    best = min(best, dp[r - 1][c + 1])
                dp[r][c] = matrix[r][c] + best
        return min(dp[-1])

