class Solution:
    def minFallingPathSum(self, matrix: list[list[int]]) -> int:
        dp = matrix[0][:]
        n = len(dp)
        for r in range(1, n):
            old = dp[:]
            for c in range(n):
                best = old[c]
                if c:
                    best = min(best, old[c - 1])
                if c + 1 < n:
                    best = min(best, old[c + 1])
                dp[c] = matrix[r][c] + best
        return min(dp)

